generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol ?totalDeposit ?totalRebalance WHERE {
  {
    SELECT ?riskTol (SUM(xsd:decimal(?depositAmt)) AS ?totalDeposit) WHERE {
      ?cf a wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?inv wm:riskTolerance ?riskTol .
      ?cf wm:type ?cfType .
      FILTER(CONTAINS(LCASE(STR(?cfType)), "deposit"))
      ?cf wm:amount ?depositAmt .
    } GROUP BY ?riskTol
  }
  {
    SELECT ?riskTol (SUM(xsd:decimal(?rebalanceAmt)) AS ?totalRebalance) WHERE {
      ?ra a wm:RebalancingAction .
      ?ra wm:rebalancingActionOfInvestor ?inv .
      ?inv wm:riskTolerance ?riskTol .
      ?ra wm:amount ?rebalanceAmt .
    } GROUP BY ?riskTol
  }
}

